 const path = require('path')
 const webpackConfig = require('@nextcloud/webpack-vue-config')
 const webpackRules = require('@nextcloud/webpack-vue-config/rules')
 const BabelLoaderExcludeNodeModulesExcept = require('babel-loader-exclude-node-modules-except')
 const TerserPlugin = require('terser-webpack-plugin')

 webpackConfig.entry = {
 	'admin-settings': path.join(__dirname, 'src', 'mainAdminSettings.js'),
 	collections: path.join(__dirname, 'src', 'collections.js'),
 	main: path.join(__dirname, 'src', 'main.js'),
 	'files-sidebar': [
 		path.join(__dirname, 'src', 'mainFilesSidebar.js'),
 		path.join(__dirname, 'src', 'mainFilesSidebarLoader.js'),
 	],
 	'public-share-auth-sidebar': path.join(__dirname, 'src', 'mainPublicShareAuthSidebar.js'),
 	'public-share-sidebar': path.join(__dirname, 'src', 'mainPublicShareSidebar.js'),
 	flow: path.join(__dirname, 'src', 'flow.js'),
 	dashboard: path.join(__dirname, 'src', 'dashboard.js'),
 	deck: path.join(__dirname, 'src', 'deck.js'),
 }

 // Edit JS rule
 webpackRules.RULE_JS.exclude = BabelLoaderExcludeNodeModulesExcept([
 	'@juliushaertl/vue-richtext',
 	'@nextcloud/event-bus',
 	'@nextcloud/vue-dashboard',
 	'ansi-regex',
 	'color.js',
 	'fast-xml-parser',
 	'hot-patcher',
 	'nextcloud-vue-collections',
 	'semver',
 	'strip-ansi',
 	'tributejs',
 	'vue-resize',
 	'webdav',
 ])

 // Replaces rules array
 webpackConfig.module.rules = Object.values(webpackRules)

 webpackConfig.module.rules.push({
 	/**
 	 * webrtc-adapter main module does no longer provide
 	 * "module.exports", which is expected by some elements using it
 	 * (like "attachmediastream"), so it needs to be added back with
 	 * a plugin.
 	 */
 	test: /node_modules\/webrtc-adapter\/.*\.js$/,
 	loader: 'babel-loader',
 	options: {
 		plugins: ['add-module-exports'],
 		presets: [
 			/**
 			 * From "add-module-exports" documentation:
 			 * "webpack doesn't perform commonjs transformation for
 			 * codesplitting. Need to set commonjs conversion."
 			 */
 			['@babel/env', { modules: 'commonjs' }],
 		],
 	},
 })

 webpackConfig.optimization.minimizer = [
 	new TerserPlugin({
 		terserOptions: {
 			output: {
 				comments: false,
 			},
 		},
 		extractComments: false,
 	}),
 ]

 module.exports = webpackConfig

diff --git a/app/src/components/RightSidebar/Participants/ParticipantsList/Participant/Participant.spec.js b/app/src/components/RightSidebar/Participants/ParticipantsList/Participant/Participant.spec.js
index 0000000..0000000 100644
--- a/app/src/components/RightSidebar/Participants/ParticipantsList/Participant/Participant.spec.js
+++ b/app/src/components/RightSidebar/Participants/ParticipantsList/Participant/Participant.spec.js
@@ -1,220 +1,220 @@
 import Vuex from 'vuex'
 import { createLocalVue, shallowMount } from '@vue/test-utils'
 import { cloneDeep } from 'lodash'
 import storeConfig from '../../../../../store/storeConfig'
 import { ATTENDEE, PARTICIPANT } from '../../../../../constants'
 import AvatarWrapper from '../../../../AvatarWrapper/AvatarWrapper'
 import Microphone from 'vue-material-design-icons/Microphone'
 import Phone from 'vue-material-design-icons/Phone'
 import Video from 'vue-material-design-icons/Video'
 import Hand from 'vue-material-design-icons/Hand'
 import ActionButton from '@nextcloud/vue/dist/Components/ActionButton'
 import ActionText from '@nextcloud/vue/dist/Components/ActionText'
 import { findActionButton } from '../../../../../test-helpers'

 import Participant from './Participant'

 describe('Participant.vue', () => {
 	let conversation
 	let participant
 	let store
 	let localVue
 	let testStoreConfig
 	let tooltipMock

 	/**
 	 * @param wrapper
 	 * @param htmlEl
 	 */
 	async function getLastTooltipValue(wrapper, htmlEl) {
 		tooltipMock.mockClear()
 		await wrapper.vm.forceEnableTooltips()

 		const filteredCalls = tooltipMock.mock.calls.filter((call) => {
 			// only keep calls on wanted node
 			return call[0] === htmlEl
 		})

 		if (filteredCalls.length) {
 			return filteredCalls[filteredCalls.length - 1][1].value
 		}

 		return null
 	}

 	beforeEach(() => {
 		localVue = createLocalVue()
 		localVue.use(Vuex)

 		tooltipMock = jest.fn()

 		participant = {
 			displayName: 'Alice',
 			inCall: PARTICIPANT.CALL_FLAG.DISCONNECTED,
 			actorId: 'alice-actor-id',
 			actorType: ATTENDEE.ACTOR_TYPE.USERS,
 			participantType: PARTICIPANT.TYPE.USER,
 			attendeeId: 'alice-attendee-id',
 			status: '',
 			statusIcon: '🌧️',
 			statusMessage: 'rainy',
 			sessionIds: [
 				'session-id-alice',
 			],
 		}

 		conversation = {
 			token: 'current-token',
 			participantType: PARTICIPANT.TYPE.USER,
 		}

 		const conversationGetterMock = jest.fn().mockReturnValue(conversation)

 		testStoreConfig = cloneDeep(storeConfig)
 		testStoreConfig.modules.tokenStore.getters.getToken = () => () => 'current-token'
 		testStoreConfig.modules.conversationsStore.getters.conversation = () => conversationGetterMock
 		store = new Vuex.Store(testStoreConfig)
 	})

 	afterEach(() => {
 		jest.clearAllMocks()
 	})

 	/**
 	 * @param participant
 	 * @param showUserStatus
 	 */
 	function mountParticipant(participant, showUserStatus = false) {
 		return shallowMount(Participant, {
 			localVue,
 			store,
 			propsData: {
 				participant,
 				showUserStatus,
 			},
 			stubs: {
 				ActionButton,
 			},
 			directives: {
 				tooltip: tooltipMock,
 			},
 			mixins: [{
 				// force tooltip display for testing
 				methods: {
 					forceEnableTooltips() {
 						this.isUserNameTooltipVisible = true
 						this.isStatusTooltipVisible = true
 					},
 				},
 			}],
 		})
 	}

 	describe('avatar', () => {
 		test('renders avatar', () => {
 			const wrapper = mountParticipant(participant)
 			const avatarEl = wrapper.findComponent(AvatarWrapper)
 			expect(avatarEl.exists()).toBe(true)

 			expect(avatarEl.props('id')).toBe('alice-actor-id')
 			expect(avatarEl.props('disableTooltip')).toBe(true)
 			expect(avatarEl.props('disableMenu')).toBe(false)
 			expect(avatarEl.props('showUserStatus')).toBe(false)
 			expect(avatarEl.props('preloadedUserStatus')).toStrictEqual({
 				icon: '🌧️',
 				message: 'rainy',
 				status: null,
 			})
 			expect(avatarEl.props('name')).toBe('Alice')
 			expect(avatarEl.props('source')).toBe(ATTENDEE.ACTOR_TYPE.USERS)
 			expect(avatarEl.props('offline')).toBe(false)
 		})

 		test('renders avatar with enabled status', () => {
 			const wrapper = mountParticipant(participant, true)
 			const avatarEl = wrapper.findComponent(AvatarWrapper)
 			expect(avatarEl.exists()).toBe(true)

 			expect(avatarEl.props('showUserStatus')).toBe(true)
 		})

 		test('renders avatar with guest name when empty', () => {
 			participant.displayName = ''
 			participant.participantType = PARTICIPANT.TYPE.GUEST
 			const wrapper = mountParticipant(participant)
 			const avatarEl = wrapper.findComponent(AvatarWrapper)
 			expect(avatarEl.exists()).toBe(true)

 			expect(avatarEl.props('name')).toBe('Guest')
 		})

 		test('renders avatar with unknown name when empty', () => {
 			participant.displayName = ''
 			const wrapper = mountParticipant(participant, true)
 			const avatarEl = wrapper.findComponent(AvatarWrapper)
 			expect(avatarEl.exists()).toBe(true)

